def venture(key,minimum,fraction,weight,gain,loss,**extra):
    prof(key,minimum,branch(weight,[{'op':'venture','stake_fraction':fraction,'gross_multiple':gain,**extra},stat(stress=4)]),branch(100-weight,[{'op':'venture','stake_fraction':fraction,'gross_multiple':loss,**extra},stat(stress=12)]))
