EVENTS=[]
def add_group(code,name,age,raw):
    for i,line in enumerate(raw.strip().splitlines(),1):
        parts=line.split('|'); assert len(parts)==5,(code,i,len(parts))
        title,prompt,*cs=parts
        choices=[]
        for n,c in enumerate(cs):
            bits=c.split('~'); assert len(bits) in (3,4),(code,i,c)
            label,profile,*texts=bits; p=P[profile]
            assert len(texts)==len(p['outcomes']),(code,i,profile)
            outcomes=[]
            for j,(txt,o) in enumerate(zip(texts,p['outcomes'])):
                outcomes.append({'id':f'{code}{i:02d}_{n+1}_{j+1}','weight':o['weight'],'text':txt,'effects':o['effects'],'schedule':[]})
            choices.append({'id':f'{code}{i:02d}_{n+1}','label':label,'profile':profile,'requirements':{'min_cash_yuan':p['min_cash_yuan'],'all':p['prerequisites']},'outcomes':outcomes})
        EVENTS.append({'id':f'{code}{i:02d}','category':name,'kind':'personal','title':title,'age_min':age[0],'age_max':age[1],'required_flags':[],'excluded_flags':[],'weight':10,'priority':40,'cooldown_turns':0,'max_occurrences':1,'prompt':prompt,'choices':choices})

