def add_growth_event(eid,age,title,prompt,profiles,required=None,excluded=None,flag=None):
    choices=[]
    for n,profile in enumerate(profiles,1):
        p=P[profile];outcomes=[]
        for j,o in enumerate(p['outcomes'],1):
            effects=json.loads(json.dumps(o['effects']))
            if flag: effects.append({'op':'flag','key':flag,'value':True})
            outcomes.append({'id':f'{eid}_{n}_{j}','weight':o['weight'],'text':PROFILE_RESULTS[profile][j-1],'effects':effects,'schedule':[]})
        choices.append({'id':f'{eid}_{n}','label':PROFILE_LABELS[profile],'profile':profile,'requirements':{'min_cash_yuan':p['min_cash_yuan'],'all':p['prerequisites']},'outcomes':outcomes})
    EVENTS.append({'id':eid,'category':'成长年记','kind':'personal','title':title,'age_min':age,'age_max':age,'required_flags':required or [],'excluded_flags':excluded or [],'weight':10,'priority':65,'cooldown_turns':0,'max_occurrences':1,'prompt':prompt,'choices':choices})
for age,variants in GROWTH_YEARS.items():
    profiles=['family','self_study','rest'] if age<6 else ['school','self_study','family'] if age<12 else ['school','self_study','rest'] if age<16 else ['school','family','observe']
    for suffix,(title,prompt) in zip('AB',variants): add_growth_event(f'AGE{age:02d}{suffix}',age,title,prompt,profiles,flag='stock_aware' if age==16 else None)
