# Outcome-based flags supplement the engine's derived state flags.
for e in EVENTS:
    for c in e['choices']:
        for i,o in enumerate(c['outcomes']):
            effects=list(o['effects'])
            # Avoid mutating shared templates.
            o['effects']=effects
            def flag(k): effects.append({'op':'flag','key':k,'value':True})
            if c['profile']=='ponzi':
                flag('ponzi_exposure')
                flag('ponzi_paid' if i==0 else 'ponzi_loss')
            if c['profile']=='angel': flag('angel_investor')
            if c['profile'] in ('business','expand') and i==0: flag('business_owner')
            if c['profile']=='options' and i==0: flag('option_big_win')
            if c['profile'] in ('stock','allin') and i==0: flag('has_realized_stock_gain')
            if c['profile']=='contract' and i==1: flag('had_margin_crisis')
            if e['id']=='ANG01': flag('knows_xuzhou')
            if e['id'].startswith('REC') and c['profile'] in ('work','job','hustle','business') and i==0: flag('rebuilding')
